BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('55bb0115-8ddd-5ddc-a906-ea3711df4bf6', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Em SQL, a comparação comum NULL = 5 produz:', '["O inteiro zero.","TRUE.","FALSE em todos os contextos.","UNKNOWN.","Uma string vazia."]'::jsonb, 3, 'Comparações comuns com marcador nulo não recebem um valor booleano clássico determinado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.2, páginas 932–938 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3a717833-5bdd-519f-8cb8-8d6ac2595419', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Na lógica trivalorada SQL, NOT UNKNOWN resulta em:', '["Uma exceção obrigatória.","TRUE.","NULL numérico igual a zero.","FALSE.","UNKNOWN."]'::jsonb, 4, 'A negação preserva o valor lógico desconhecido.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.2, páginas 932–938 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('32d022f3-adc2-5571-9bdc-72794a599c86', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Na lógica trivalorada SQL, TRUE AND UNKNOWN resulta em:', '["FALSE.","UNKNOWN.","Uma string vazia.","Zero.","TRUE."]'::jsonb, 1, 'O resultado depende da condição desconhecida, pois o outro operando é verdadeiro.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.2, páginas 932–938 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9c8ece33-f15c-5ee8-8e9f-3f277ef5240c', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Na lógica trivalorada SQL, FALSE AND UNKNOWN resulta em:', '["Um erro de chave.","UNKNOWN.","Uma relação vazia por definição.","FALSE.","TRUE."]'::jsonb, 3, 'Um operando falso torna falsa a conjunção independentemente do outro.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.2, páginas 932–938 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f541d5d6-1475-53f3-8d96-979019cb9f3a', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Na lógica trivalorada SQL, TRUE OR UNKNOWN resulta em:', '["UNKNOWN.","FALSE.","TRUE.","Uma exceção.","Um número nulo."]'::jsonb, 2, 'Um operando verdadeiro basta para tornar verdadeira a disjunção.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.2, páginas 932–938 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d1deb54e-02fc-5ed1-9b3c-e96c869a98d6', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'Na lógica trivalorada SQL, FALSE OR UNKNOWN resulta em:', '["TRUE.","Uma string vazia.","UNKNOWN.","Um erro de tipo obrigatório.","FALSE."]'::jsonb, 2, 'A verdade da disjunção ainda depende do operando desconhecido.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.2, páginas 932–938 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ae53fb90-9de4-5dde-9e2b-9e4add5e73ff', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Uma cláusula WHERE seleciona linhas cuja condição resulta em:', '["TRUE.","Somente UNKNOWN.","Qualquer valor que não seja zero.","TRUE ou UNKNOWN.","FALSE ou UNKNOWN."]'::jsonb, 0, 'Condições falsas ou desconhecidas não qualificam a linha para o resultado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.7, páginas 953–960 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1752959e-7861-5c47-b678-d8516a4638ac', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Fácil', 'Qual teste SQL verifica diretamente a presença de marcador nulo?', '["IS NULL.","= 0.","= NULL.","= UNKNOWN como substituto universal.","<> NULL."]'::jsonb, 0, 'IS NULL é um teste específico; a comparação comum com NULL não é equivalente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.7, páginas 953–960 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f4f4de9b-7148-5c39-80f5-8bb50ef36e91', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'A expressão NULL = NULL em SQL é avaliada como:', '["FALSE obrigatoriamente.","UNKNOWN.","Uma tupla vazia.","Zero.","TRUE."]'::jsonb, 1, 'A igualdade comum não identifica dois marcadores nulos como um valor conhecido igual.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.7, páginas 953–960 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('43c2e153-f683-571b-826e-b8153843c1a9', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Difícil', 'Se P é UNKNOWN, P OR NOT P produz, na lógica trivalorada discutida:', '["TRUE.","Uma confirmação.","Um inteiro.","FALSE.","UNKNOWN."]'::jsonb, 4, 'O terceiro valor impede aplicar sem exame certas equivalências da lógica bivalorada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.3, páginas 939–943 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5b1ed8a3-0bf1-5465-b4c9-9c7e26068aee', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Para valores 10, 20 e NULL, COUNT(coluna) retorna:', '["2.","1.","NULL.","3.","0."]'::jsonb, 0, 'COUNT da expressão conta apenas resultados não nulos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.7, páginas 953–960 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0457ebf8-3499-5c2a-87c0-25531a923053', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Para três linhas, uma contendo NULL na coluna consultada, COUNT(*) retorna:', '["2.","3.","NULL.","1.","0."]'::jsonb, 1, 'COUNT(*) conta linhas, independentemente de nulos em colunas particulares.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.7, páginas 953–960 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ee1d31ee-1933-5132-a7d6-edeee131ab81', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Para valores 10, 20 e NULL, AVG(coluna) resulta em:', '["30.","15.","10.","0.","NULL obrigatoriamente."]'::jsonb, 1, 'AVG ignora o marcador nulo; não o trata automaticamente como zero.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.7, páginas 953–960 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('458dd776-65e7-5fdc-8a64-0d3349fdb7d0', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Fácil', 'Uma coluna de chave primária SQL pode aceitar NULL?', '["Sim, somente na primeira linha.","Sim, se seu tipo for texto.","Sim, quando referenciada por outra tabela.","Sim, se o índice estiver ordenado.","Não."]'::jsonb, 4, 'A chave primária SQL exige identificação não nula.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.4, páginas 944–947 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f773f17d-c04b-51b5-9e22-75a39c30bfd3', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Uma chave estrangeira anulável significa necessariamente que toda linha deve possuir referência preenchida?', '["Sim, quando a tabela contém índices.","Sim, REFERENCES implica NOT NULL em qualquer declaração.","Não; nulos e regras de correspondência precisam ser considerados.","Sim, por definição de coluna.","Não, porque chaves estrangeiras nunca são verificadas."]'::jsonb, 2, 'Obrigatoriedade e integridade da referência são requisitos relacionados, mas distintos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.4, páginas 944–947 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('68fa96d9-93d2-5e86-b673-dd150e48089d', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Uma junção externa à esquerda preserva:', '["Apenas linhas com chaves nulas.","Todas as combinações do produto sem filtro.","Somente as linhas do lado direito.","Todas as linhas do lado esquerdo, usando nulos nos campos direitos sem correspondência.","Somente linhas com correspondência dos dois lados."]'::jsonb, 3, 'O preenchimento de campos ausentes distingue a junção externa da interna.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.5, páginas 948–951 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6c69f9f6-039d-59db-88c4-e1329fc5f9cb', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Difícil', 'Um filtro WHERE sobre coluna direita após LEFT JOIN pode eliminar linhas sem correspondência porque:', '["A condição pode resultar UNKNOWN nos campos preenchidos com NULL.","NULL é sempre igual a qualquer valor.","Toda coluna direita vira chave primária.","LEFT JOIN nunca conserva linhas da esquerda.","WHERE é executado como COMMIT."]'::jsonb, 0, 'É necessário considerar o efeito do filtro sobre as linhas estendidas com nulos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.7, páginas 953–960 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('488bc0b3-6053-596f-a085-7889b8ac7e29', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Usar -1 como valor especial para informação ausente exige cuidado porque:', '["Ele garante média correta sem tratamento.","Ele passa a ser automaticamente NULL.","O valor sentinela pode contaminar cálculos e precisa de semântica explícita.","Ele elimina todas as restrições.","Ele impede qualquer armazenamento."]'::jsonb, 2, 'Um valor convencional não equivale ao mecanismo de ausência nem resolve toda ambiguidade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.6, páginas 952 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('97de7848-4535-583f-b60c-0749d784af43', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Qual expressão SQL escolhe o primeiro argumento não nulo entre salario e 0?', '["salario <> NULL.","NULL = 0.","salario = NULL.","COALESCE(salario, 0).","COUNT(*)."]'::jsonb, 3, 'A substituição é explícita; usar zero envolve uma decisão semântica da aplicação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.7, páginas 953–960 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6714806d-4a20-5707-8097-73274160b7cf', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Difícil', 'Uma consulta usa x NOT IN (1, NULL). Para x=2, por que a linha não é selecionada?', '["Porque NULL equivale a todos os inteiros.","Porque a tabela não pode conter 2.","Porque NOT IN é sempre falso.","Porque 2 é igual a 1.","A comparação com o nulo torna o predicado UNKNOWN."]'::jsonb, 4, 'A negação não converte desconhecido em verdadeiro, exigindo cuidado com nulos em subconsultas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.3, páginas 939–943 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
